<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,allPages} from '../services/api';import {usePage} from '../services/usePage';import Notice from '../components/Notice.vue';import PrivateImage from '../components/PrivateImage.vue';import BoxEditor from '../components/BoxEditor.vue'
const datasets=ref<any[]>([]),dataset=ref(''),images=ref<any[]>([]),selected=ref<string[]>([]),variants=ref<any[]>([]),preview=ref<any>(null),recipe=ref({size:800,brightness:1,contrast:1,crop:[0,0,1,1]}),accepted=ref(false);const {error,success,busy,act}=usePage()
onMounted(()=>act(async()=>{datasets.value=await allPages('datasets/')}))
const load=()=>act(async()=>{images.value=await allPages(`images/?dataset=${dataset.value}`);selected.value=[];variants.value=[];preview.value=null})
const process=()=>act(async()=>{await api.post('jobs/preprocessing/',{images:selected.value,...recipe.value})},'Trabajo registrado. Consulta su progreso en Trabajos y actualiza los derivados al terminar.')
const view=()=>act(async()=>{variants.value=await allPages('variants/');variants.value=variants.value.filter(v=>images.value.some(i=>i.id===v.image));preview.value=variants.value[0]||null})
const freezeDerived=()=>act(async()=>{const mapping:Record<string,string>={};for(const v of variants.value)if(!mapping[v.image])mapping[v.image]=v.id;await api.post(`datasets/${dataset.value}/freeze/`,{variants:mapping,reviewed_variants:accepted.value,seed:42})},'Versión congelada: último derivado disponible por imagen; originales para las demás.')
</script>
<template><h1 class="heading">Laboratorio de imágenes</h1><p class="subheading mb-7">Ajusta tus imágenes sin perder el original. El relleno es blanco y conserva las proporciones de la fruta.</p><Notice :error="error" :success="success"/><div class="grid items-start gap-6 lg:grid-cols-[1fr_320px]"><section class="card"><label class="label">Dataset</label><select v-model="dataset" @change="load" class="input mb-4"><option value="">Seleccionar colección</option><option v-for="d in datasets" :key="d.id" :value="d.id">{{d.name}}</option></select><div class="mb-4 flex gap-2"><button class="btn-secondary" @click="selected=images.slice(0,200).map(i=>i.id)">Seleccionar hasta 200</button><button class="btn-secondary" @click="selected=[]">Limpiar</button></div><div class="grid max-h-[520px] grid-cols-3 gap-3 overflow-auto sm:grid-cols-4"><label v-for="img in images" :key="img.id" class="relative overflow-hidden rounded-xl border" :class="selected.includes(img.id)?'border-emerald-600 ring-2 ring-emerald-100':'border-slate-200'"><input type="checkbox" v-model="selected" :value="img.id" class="absolute left-2 top-2 z-10 h-4 w-4 accent-emerald-700"/><PrivateImage :src="`images/${img.id}/file/`" class="aspect-square w-full object-contain"/><span class="block truncate p-2 text-[10px] text-slate-500">{{img.name}}</span></label></div><p v-if="!images.length" class="py-12 text-center text-sm text-slate-400">Selecciona un dataset para ver sus imágenes.</p></section><form @submit.prevent="process" class="card space-y-5"><h2 class="font-semibold">Receta de procesamiento</h2><div><label class="label">Resolución cuadrada</label><select v-model.number="recipe.size" class="input"><option :value="640">640 × 640</option><option :value="800">800 × 800</option></select></div><div v-for="key in (['brightness','contrast'] as const)" :key="key"><label class="label">{{key==='brightness'?'Brillo':'Contraste'}} · {{recipe[key]}}</label><input class="w-full accent-emerald-700" type="range" min="0.5" max="1.5" step="0.05" v-model.number="recipe[key]"/></div><div><label class="label">Recorte normalizado (0–1)</label><div class="grid grid-cols-2 gap-2"><label v-for="(label,i) in ['Izquierda','Arriba','Derecha','Abajo']" :key="label" class="text-[10px] text-slate-400">{{label}}<input v-model.number="recipe.crop[i]" type="number" min="0" max="1" step=".01" class="input"/></label></div></div><button class="btn w-full" :disabled="busy||!selected.length">Procesar {{selected.length}} imágenes</button><p class="text-xs leading-5 text-slate-400">Se transforman las cajas junto con la imagen. Revisa las lesiones recortadas antes de entrenar.</p><RouterLink to="/jobs" class="block text-center text-xs font-semibold text-emerald-700">Ver trabajos →</RouterLink></form></div>
<section class="card mt-6"><div class="mb-4 flex flex-wrap justify-between gap-3"><h2 class="font-semibold">Comparación y revisión de derivados</h2><button @click="view" class="btn-secondary" :disabled="!dataset||busy">Actualizar derivados</button></div><select v-if="variants.length" v-model="preview" class="input mb-5"><option v-for="v in variants" :value="v" :key="v.id">{{images.find(i=>i.id===v.image)?.name}} · {{new Date(v.created_at).toLocaleString()}}</option></select><div v-if="preview" class="grid gap-4 md:grid-cols-2"><div><p class="label">Original</p><PrivateImage :src="`images/${preview.image}/file/`" class="aspect-square w-full object-contain"/></div><div><p class="label">Derivado · cajas transformadas</p><BoxEditor :src="`variants/${preview.id}/file/`" :boxes="preview.annotations" :width="preview.width" :height="preview.height" readonly/></div></div><p v-else class="text-sm text-slate-400">Aquí podrás comparar originales y derivados después de ejecutar el worker.</p><div v-if="variants.length" class="mt-6 border-t border-slate-100 pt-5"><label class="flex items-start gap-2 text-xs leading-5 text-slate-500"><input type="checkbox" v-model="accepted" class="mt-1"/>He revisado el último derivado de cada imagen y sus cajas. Acepto usarlos en una nueva versión; se mantienen las particiones existentes y se usan originales donde no hay derivados.</label><button @click="freezeDerived" :disabled="!accepted||busy" class="btn mt-4">Congelar versión preprocesada</button></div></section></template>
